using SoulsFormats;
using System.Numerics;
using System.Security.Cryptography;

// Each exact authored leaf has its own native keyframed solid. Keeping two
// independent carriers avoids inventing a multi-body solver/animation ABI.
internal static class MapCrestGateAssets {
    internal sealed record Leaf(int Model,int SourceVisualBone,int SourceAnimationBone,byte[] Bundle,DoorPhysics.Box LocalBox,Matrix4x4 PhysicalReference,Matrix4x4 AnimationReference,int Vertices,int Frames,float Duration);
    static void Need(bool b,string why){if(!b)throw new InvalidDataException("Crest gate asset: "+why);}
    static Matrix4x4 Affine(Matrix4x4 m){m.M14=m.M24=m.M34=0;m.M44=1;return m;}
    static int Bone(FLVER2.Mesh m,FLVER.Vertex v)=>SkinRetarget.Bone(m,v.BoneIndices[0]);
    internal static FLVER2 SelectLeaf(FLVER2 authored,int bone) {
        var source=FLVER2.Read(authored.Write());source.Meshes.Clear();
        foreach(var original in authored.Meshes){Need(!original.UseBoneWeights,"source rigid leaf mesh required");var selected=original.Vertices.Select((v,i)=>(v,i)).Where(x=>Bone(original,x.v)==bone).ToArray();if(selected.Length==0)continue;var indices=selected.Select((x,i)=>(Old:x.i,New:i)).ToDictionary(x=>x.Old,x=>x.New);var triangles=new List<int>();foreach(var face in StaticMapGeometry.Faces(authored,original)){Need(face.Indices.Count%3==0,"source triangle list");for(int at=0;at<face.Indices.Count;at+=3){var tri=face.Indices.Skip(at).Take(3).ToArray();int count=tri.Count(indices.ContainsKey);Need(count is 0 or 3,"source triangle crosses the two physical leaves");if(count==3)triangles.AddRange(tri.Select(i=>indices[i]));}}Need(triangles.Count>0,"empty source leaf surface");var mesh=new FLVER2.Mesh{UseBoneWeights=false,NodeIndex=original.NodeIndex,MaterialIndex=original.MaterialIndex,BoneIndices=original.BoneIndices.ToList(),Vertices=selected.Select(x=>new FLVER.Vertex(x.v)).ToList()};mesh.VertexBuffers=original.VertexBuffers.Select(b=>new FLVER2.VertexBuffer(b.LayoutIndex){BufferIndex=b.BufferIndex}).ToList();mesh.FaceSets.Add(new(FLVER2.FaceSet.FSFlags.None,false,true,0,triangles));source.Meshes.Add(mesh);}
        Need(source.Meshes.Count>0,"missing source leaf mesh");return source;
    }
    static byte[] Physics(byte[] native,DoorPhysics.Box box,Matrix4x4 reference) {
        // Native support-vertex metadata, face connectivity, material and all
        // scene/body fixups remain intact. Transform source box points/planes
        // into the source object's reference frame without an AABB expansion.
        var result=DoorPhysics.Fit(native,box);var p=new NativeAnimation.Pack(result);const int vertices=784,planes=912;
        void F(int at,float value)=>BitConverter.GetBytes(value).CopyTo(result,p.Data+at);
        for(int i=0;i<8;i++){int at=vertices+i*16;var point=Vector3.Transform(new(p.Float(at),p.Float(at+4),p.Float(at+8)),reference);F(at,point.X);F(at+4,point.Y);F(at+8,point.Z);}
        var center=Vector3.Transform(box.Center,reference);for(int i=0;i<6;i++){int at=planes+i*16;var normal=new Vector3(p.Float(at),p.Float(at+4),p.Float(at+8));float half=Vector3.Dot(Vector3.Abs(normal),box.Half);var transformed=Vector3.TransformNormal(normal,reference);Need(Math.Abs(transformed.LengthSquared()-1)<.000001f,"non-rigid source box transform");F(at,transformed.X);F(at+4,transformed.Y);F(at+8,transformed.Z);F(at+12,-Vector3.Dot(transformed,center)-half);}return result;
    }
    internal static IReadOnlyList<Leaf> Convert(string model,int firstModel,byte[] sourceBytes,byte[] nativeBytes,FLVER2 surface,Func<IFlverMaterial,FLVER2.Material> materialFactory) {
        Need(model is "o2110" or "o2111","unsupported source gate");string expected=model=="o2110"?"865d281c8ab1a1646e340d35e20ec1d701ed01fe261de90eb1ad186c3586e796":"eda91ae85ad41f11e4e1e77b0c5293015a4646a6c4c5d57b69f95fa37378dcce";Need(System.Convert.ToHexStringLower(SHA256.HashData(sourceBytes))==expected,"audited source gate changed");
        var bank=BND3.Read(sourceBytes);var authored=FLVER2.Read(bank.Files.Single(f=>f.ID==200).Bytes);Need(authored.Nodes.Select(n=>n.Name).SequenceEqual(new[]{model+"_01",model+"_02","Dummy",model})&&authored.Nodes.All(n=>n.ParentIndex==-1),"source two-leaf visual nodes");
        var sourceAnims=BND3.Read(bank.Files.Single(f=>f.ID==400).Bytes);var clip=SourceAnimation.Decode(sourceAnims.Files.Single(f=>f.ID==1000000).Bytes.ToArray(),sourceAnims.Files.Single(f=>f.ID==1).Bytes.ToArray());int count=model=="o2110"?101:201;Need(clip.Bones.Select(b=>b.Name).SequenceEqual(new[]{model,model+"_01",model+"_02"})&&clip.Bones.Select(b=>b.Parent).SequenceEqual(new[]{-1,0,0})&&clip.FrameCount==count,"source opening rig/timing");var reference=NativeAnimation.Worlds(clip.Bones.Select(b=>Matrix4x4.CreateScale(b.Scale)*Matrix4x4.CreateFromQuaternion(b.Rotation)*Matrix4x4.CreateTranslation(b.Translation)).ToArray(),clip.Bones.Select(b=>b.Parent).ToArray());
        var physics=bank.Files.Single(f=>f.ID==300).Bytes.ToArray();var t=new SourceCollision.Tag(physics);var bodies=t.Items.Where(i=>i.Count==1&&t.Name(i.Type)=="hkpRigidBody").ToArray();Need(bodies.Length==2,"source exact two-body gate");var leaves=new List<Leaf>();
        for(int leaf=0;leaf<2;leaf++){var output=BND4.Read(nativeBytes);var rigVisual=FLVER2.Read(output.Files.Single(f=>f.ID==200).Bytes);var selection=SelectLeaf(authored,leaf);var visual=MapBreakables.RetargetVisual(selection,rigVisual,surface,"DS1R",Vector3.One,new Dictionary<int,int>{{leaf,1}},materialFactory);
            // Source action marker100 is attached to stationary Dummy, never a
            // leaf. The owned event prompt and player facing consume this root.
            visual.Dummies.Clear();foreach(var marker in authored.Dummies.Where(d=>d.ParentBoneIndex==2)){Need(marker.AttachBoneIndex==-1,"unsupported source marker attachment");var copy=new FLVER.Dummy(marker){ParentBoneIndex=0};visual.Dummies.Add(copy);}Need(visual.Dummies.Any(d=>d.ReferenceID==100),"source front action marker");output.Files.Single(f=>f.ID==200).Bytes=visual.Write();
            string Name(SourceCollision.Tag.Item b){var n=t.Reference(t.Nested(b.Type,b.At,"name").At);return SourceAnimation.DecodeBoneName(physics.AsSpan(n.At,n.Count-1).ToArray());}var body=bodies.Single(b=>Name(b)==model+"_0"+(leaf+1));var rest=Affine(t.Transform(t.Nested(body.Type,body.At,"motion","motionState","transform").At));var translated=t.Reference(t.Nested(body.Type,body.At,"collidable","shape").At);Need(t.Name(translated.Type)=="hkpConvexTranslateShape","source translated solid");var shape=t.Reference(t.Nested(translated.Type,translated.At,"childShape","childShape").At);Need(t.Name(shape.Type)=="hkpBoxShape","unsupported source solid");var box=new DoorPhysics.Box(t.Vector(t.Nested(shape.Type,shape.At,"halfExtents").At),t.Vector(t.Nested(translated.Type,translated.At,"translation").At),BitConverter.ToSingle(physics,t.Nested(shape.Type,shape.At,"radius").At));output.Files.Single(f=>f.ID==300).Bytes=Physics(output.Files.Single(f=>f.ID==300).Bytes.ToArray(),box,rest);
            var animations=BND4.Read(output.Files.Single(f=>f.ID==400).Bytes);var rig=NativeAnimation.Skeleton(animations.Files.Single(f=>f.ID==1000000).Bytes.ToArray());Need(rig.Names.SequenceEqual(new[]{"o241013","o241013_00"}),"native leaf rig changed");Need(Matrix4x4.Invert(reference[leaf+1],out var inverse),"singular source hinge reference");
            foreach(int id in new[]{0,1,2,3}){int frames=id is 0 or 3?2:clip.FrameCount;var samples=new List<Matrix4x4>();for(int frame=0;frame<frames;frame++){float time=id==0?0:id==3?clip.Duration:id==2?clip.Duration-frame*clip.FrameDuration:frame*clip.FrameDuration;var worlds=NativeAnimation.Worlds(clip.Sample(Math.Clamp(time,0,clip.Duration)),clip.Bones.Select(b=>b.Parent).ToArray());samples.Add(rig.Local[0]);samples.Add(rig.Local[1]*inverse*worlds[leaf+1]);}animations.Files.Single(f=>f.ID==1000000000+id).Bytes=NativeSpline.Encode(samples,2,frames,clip.FrameDuration,rig.Name,rig.Names);}
            // Native door cue begins at0; retain its known event/group ABI and
            // omit the native closing cue that no longer matches source timing.
            var taeFile=animations.Files.Single(f=>f.ID==3000000);var tae=TAE.Read(taeFile.Bytes);foreach(var a in tae.Animations.Where(a=>leaf==1||a.ID!=1)){a.Events.Clear();a.EventGroups.Clear();}taeFile.Bytes=tae.Write();output.Files.Single(f=>f.ID==400).Bytes=animations.Write();int target=firstModel+leaf;foreach(var f in output.Files)f.Name=f.Name.Replace("o241013","o"+target,StringComparison.Ordinal);leaves.Add(new(target,leaf,leaf+1,output.Write(DCX.Type.DCX_DFLT_10000_44_9),box,rest,reference[leaf+1],visual.Meshes.Sum(m=>m.Vertices.Count),clip.FrameCount,clip.Duration));
        }Need(leaves.Sum(l=>l.Vertices)==authored.Meshes.Sum(m=>m.Vertices.Count),"source vertex partition lost/duplicated geometry");return leaves;
    }
}
